// Generate src/api/schema.d.ts from the wrapper's committed contract
// (../sso-wrapper/openapi.json, regenerated by the wrapper's OpenApiContractTest).
// The wrapper is the source of truth. The reference FastAPI contract
// (openapi.reference.json) remains only as an opt-in fallback:
//   GEN_API_SOURCE=reference npm run gen:api
import { existsSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { execFileSync } from "node:child_process";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const wrapper = resolve(root, "../sso-wrapper/openapi.json");
const reference = resolve(root, "openapi.reference.json");

const paths = (file) => {
  const doc = JSON.parse(readFileSync(file, "utf8"));
  const out = new Set();
  for (const [p, ops] of Object.entries(doc.paths ?? {})) for (const m of Object.keys(ops)) out.add(`${m.toUpperCase()} ${p}`);
  return out;
};

const source = process.env.GEN_API_SOURCE ?? "wrapper";
const input = source === "reference" ? reference : wrapper;
if (!existsSync(input)) {
  console.error(`gen:api: ${input} not found (GEN_API_SOURCE=${source}).`);
  process.exit(1);
}
if (source !== "reference" && existsSync(reference)) {
  // Informational: operations the reference had that the wrapper does not (by method + path shape).
  const shape = (s) => s.replace(/\{[^}]+\}/g, "{}");
  const have = new Set([...paths(wrapper)].map(shape));
  const missing = [...paths(reference)].filter((p) => !have.has(shape(p)));
  if (missing.length) console.warn(`gen:api: wrapper lacks ${missing.length} reference operation(s): ${missing.join(", ")}`);
}
console.log(`gen:api <- ${input}`);

// Known wrapper doc defect: the institution-admin endpoints resolve their
// InstitutionContext from `?institution=` (CurrentInstitution / InstitutionWebConfig),
// but springdoc documents the resolved argument itself as a required query
// object `ctx`. Rewrite it to the real parameter so typed calls are correct.
const doc = JSON.parse(readFileSync(input, "utf8"));
let rewritten = 0;
for (const ops of Object.values(doc.paths ?? {})) {
  for (const op of Object.values(ops)) {
    if (!op || !Array.isArray(op.parameters)) continue;
    const i = op.parameters.findIndex((p) => p.in === "query" && p.name === "ctx");
    if (i < 0) continue;
    rewritten += 1;
    const has = op.parameters.some((p) => p.in === "query" && p.name === "institution");
    if (has) op.parameters.splice(i, 1);
    else
      op.parameters[i] = {
        name: "institution",
        in: "query",
        required: false,
        description: "Institution slug — needed by platform admins and admins of several institutions.",
        schema: { type: "string" },
      };
  }
}
if (rewritten) console.warn(`gen:api: rewrote ${rewritten} undocumented 'ctx' query params to 'institution' (wrapper doc defect).`);
const tmp = resolve(mkdtempSync(resolve(tmpdir(), "gen-api-")), "openapi.json");
writeFileSync(tmp, JSON.stringify(doc));

execFileSync(
  process.execPath,
  [resolve(root, "node_modules/openapi-typescript/bin/cli.js"), tmp, "-o", resolve(root, "src/api/schema.d.ts")],
  { stdio: "inherit" },
);
